import React, { useState } from 'react'
import useTw from './tw'

const EMPTY = { year: '', branch: '', course: '' }

const YEARS = ['1st', '2nd', '3rd', '4th']

const COURSES = [
  { value: 'Polytechnic', label: 'Polytechnic', icon: 'fa-screwdriver-wrench' },
  { value: 'Btech', label: 'B.Tech', icon: 'fa-graduation-cap' },
  { value: 'MBA', label: 'MBA', icon: 'fa-briefcase' },
]

const BRANCHES = [
  { value: 'CSE', label: 'Computer Science', code: 'CSE', icon: 'fa-laptop-code' },
  { value: 'EC', label: 'Electronics & Comm.', code: 'EC', icon: 'fa-tower-broadcast' },
  { value: 'ME', label: 'Mechanical', code: 'ME', icon: 'fa-gears' },
  { value: 'CE', label: 'Civil', code: 'CE', icon: 'fa-building' },
  { value: 'HR', label: 'Human Resources', code: 'HR', icon: 'fa-users' },
  { value: 'Finance', label: 'Finance', code: 'Fin', icon: 'fa-chart-line' },
]

const ring = 'peer-focus-visible:ring-2 peer-focus-visible:ring-teal-400 peer-focus-visible:ring-offset-0'

/* Section heading with a tick once the group has a value */
const GroupTitle = ({ t, title, done }) => (
  <div className="mb-2 flex items-center justify-between">
    <h4 className={`text-sm font-bold ${t.text}`}>{title}</h4>
    {done && <i className={`fa-solid fa-circle-check text-sm ${t.ok}`} aria-label="chosen"></i>}
  </div>
)

/* One selectable row (course / branch) */
const Row = ({ t, name, option, checked, onChange }) => (
  <label className="relative block cursor-pointer">
    <input type="radio" name={name} value={option.value} checked={checked} onChange={onChange} className="peer sr-only" />
    <div
      className={`flex items-center gap-3 rounded-lg border-2 px-3 py-2 transition ${ring} ${
        checked ? t.tileOn : t.tile
      }`}
    >
      <span
        className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-md text-sm ${
          checked ? t.iconOn : t.icon
        }`}
      >
        <i className={`fa-solid ${option.icon}`} aria-hidden="true"></i>
      </span>
      <span className="min-w-0 flex-1 truncate text-sm font-semibold">{option.label}</span>
      {option.code && (
        <span className={`text-xs font-semibold ${checked ? t.subOn : t.muted}`}>{option.code}</span>
      )}
      {checked && <i className="fa-solid fa-circle-check text-sm" aria-hidden="true"></i>}
    </div>
  </label>
)

const Filters = ({ handelsubmit }) => {
  const t = useTw()
  const [cred, setMycred] = useState(EMPTY)

  const handleChange = (e) => {
    setMycred({ ...cred, [e.target.name]: e.target.value })
  }

  const steps = [cred.year, cred.course, cred.branch]
  const doneCount = steps.filter(Boolean).length
  // The backend route needs year, course and branch together
  const isComplete = doneCount === 3

  const handleSubmit = (event) => {
    event.preventDefault()
    if (!isComplete) return
    handelsubmit(cred)
  }

  const handelreset = (e) => {
    e.preventDefault()
    setMycred(EMPTY)
    handelsubmit(null) // null = show all records
  }

  return (
    <form
      onSubmit={handleSubmit}
      onReset={handelreset}
      className={`space-y-5 rounded-2xl border p-4 shadow-sm ${t.surface} ${t.borderSoft} ${t.text}`}
    >
      {/* Header + progress */}
      <div>
        <div className="flex items-center justify-between">
          <h3 className="text-base font-bold">Filters</h3>
          <span className={`text-xs font-semibold ${t.muted}`} aria-live="polite">
            {doneCount} of 3 chosen
          </span>
        </div>
        <div className="mt-2 flex gap-1" aria-hidden="true">
          {steps.map((s, i) => (
            <span key={i} className={`h-1.5 flex-1 rounded-full transition-colors ${s ? t.barOn : t.barOff}`} />
          ))}
        </div>
      </div>

      {/* Year */}
      <fieldset>
        <legend className="sr-only">Year</legend>
        <GroupTitle t={t} title="Year" done={Boolean(cred.year)} />
        <div className="grid grid-cols-4 gap-1.5">
          {YEARS.map((y) => (
            <label key={y} className="relative block cursor-pointer">
              <input
                type="radio"
                name="year"
                value={y}
                checked={cred.year === y}
                onChange={handleChange}
                className="peer sr-only"
              />
              <div
                className={`rounded-lg border-2 py-2 text-center text-sm font-bold transition ${ring} ${
                  cred.year === y ? t.tileOn : t.tile
                }`}
              >
                {y}
              </div>
            </label>
          ))}
        </div>
      </fieldset>

      {/* Course */}
      <fieldset>
        <legend className="sr-only">Course</legend>
        <GroupTitle t={t} title="Course" done={Boolean(cred.course)} />
        <div className="space-y-1.5">
          {COURSES.map((o) => (
            <Row key={o.value} t={t} name="course" option={o} checked={cred.course === o.value} onChange={handleChange} />
          ))}
        </div>
      </fieldset>

      {/* Branch */}
      <fieldset>
        <legend className="sr-only">Branch</legend>
        <GroupTitle t={t} title="Branch" done={Boolean(cred.branch)} />
        <div className="space-y-1.5">
          {BRANCHES.map((o) => (
            <Row key={o.value} t={t} name="branch" option={o} checked={cred.branch === o.value} onChange={handleChange} />
          ))}
        </div>
      </fieldset>

      {/* Actions */}
      <div className={`border-t pt-4 ${t.borderSoft}`}>
        <div className="grid grid-cols-2 gap-2">
          <button
            type="reset"
            className={`h-10 rounded-lg border text-sm font-semibold transition hover:opacity-75 focus:outline-none focus-visible:ring-2 focus-visible:ring-teal-400 ${t.ghost}`}
          >
            Reset
          </button>
          <button
            type="submit"
            disabled={!isComplete}
            className={`h-10 rounded-lg text-sm font-semibold transition focus:outline-none focus-visible:ring-2 focus-visible:ring-teal-400 ${
              isComplete ? `${t.primary} hover:brightness-110` : `${t.disabled} cursor-not-allowed`
            }`}
          >
            Apply
          </button>
        </div>
        {!isComplete && (
          <p className={`mt-2 text-center text-xs ${t.muted}`}>Choose a year, course and branch to apply.</p>
        )}
      </div>
    </form>
  )
}

export default Filters
